using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class CooperativePuzzleChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var old=JsonUtility.FromJson<WorldPlayMemory>("{}");Require(old.Valid()&&old.Puzzle.solved==0,"Historical play data rejected");var memory=new PuzzleMemory{attempts=1};memory.Complete();Require(memory.Valid()&&memory.solved==1&&memory.enjoyment>.5f,"Puzzle outcome invalid");memory.solved=2;Require(!memory.Valid(),"Invented puzzle success accepted");memory.solved=1;memory.enjoyment=float.NaN;Require(!memory.Valid(),"Invalid enjoyment accepted");Require(CooperativePuzzle.SelectCue(false,false,false,false,false,false,false)==PuzzleCue.Unavailable&&CooperativePuzzle.SelectCue(true,false,false,false,false,false,false)==PuzzleCue.NeedsKey&&CooperativePuzzle.SelectCue(true,false,true,false,false,false,false)==PuzzleCue.WaitingForHelper&&CooperativePuzzle.SelectCue(true,false,true,true,false,false,false)==PuzzleCue.HelperApproaching&&CooperativePuzzle.SelectCue(true,false,true,true,true,false,false)==PuzzleCue.Opening&&CooperativePuzzle.SelectCue(true,false,true,true,true,true,false)==PuzzleCue.ReadyToRoll&&CooperativePuzzle.SelectCue(true,false,true,true,true,true,true)==PuzzleCue.BallPassing&&CooperativePuzzle.SelectCue(true,true,true,false,false,false,false)==PuzzleCue.Solved,"Cue states invent or hide progress");Debug.Log("BWVR_PUZZLE_MODEL_PASS: historical saves, bounded outcomes and enjoyment");}
 public static void Verify(Action<BeachBall> capture=null,Action<BeachBall> readyCapture=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var ball=slice.GetComponentInChildren<BeachBall>();var puzzle=ball.Puzzle;Require(puzzle.Available,"No puzzle placement found");var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var walker=god.GetComponent<IslandNavigator>();var nav=walker.world;float unit=nav.Scale;var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release held objects first");var gp=god.transform.position;var gr=god.transform.rotation;var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var active=ideas.Select(i=>i.gameObject.activeSelf).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);Require(!nav.TreeNavigationPending,"Wait for toy navigation update before QA");Require(!nav.SegmentClear(puzzle.Root.position-puzzle.Root.forward*unit*8,puzzle.Root.position+puzzle.Root.forward*unit*8,nav.creature),"Creature can route through fixed gate frame");var key=puzzle.Key;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f,playPreference=1};
  void Grab(CarryItem item){Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,item}),"Native pickup failed: "+item.name);}
  void Release(Vector3 at){typeof(QuestSlice).GetMethod("Release",Flags).Invoke(slice,new object[]{1,new Ray(at+Vector3.up*unit*30,Vector3.down)});}
  void Stage(){god.Interrupt("Puzzle QA stage");ball.ResetWorld();foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.transform.position+=Vector3.right*unit*300;}Require(walker.CanPlace(puzzle.Pad.transform.position-puzzle.Root.forward*unit*10,out var at),"No creature approach");god.transform.position=at;god.transform.LookAt(puzzle.Pad.transform.position);walker.ResetRoute();foreach(var c in cooldowns.Keys)if(c!=puzzle.Pad.GetComponent<CreatureAffordance>())c.cooldown=10000000;var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);Physics.SyncTransforms();}
  void Tick(float dt){ball.Advance(dt,test.paused);god.Tick(dt);}
  void Dock(){Grab(key);key.transform.position=puzzle.Socket;ball.Advance(.05f,false);Require(!puzzle.Docked&&!puzzle.Ready,"Held key powered the gate");Release(puzzle.Socket);Tick(.05f);Require(puzzle.Docked,"Native release did not dock key");}
  void Roll(){ball.PlaceOnGround(puzzle.LaunchPoint-Vector3.up*unit*ball.Radius);Require(ball.PlayerToss(puzzle.Root.forward*(12f/18),1),"Player toss rejected");}
  try{
   field.SetValue(slice,test);god.NewSeason();Stage();Require(!puzzle.Ready&&!puzzle.Pad.GetComponent<CarryItem>().CanGrab,"Unpowered / fixed pad is interactive incorrectly");Roll();float furthest=-100;for(int i=0;i<240;i++){ball.Advance(.02f,false);test.Hybrid.time+=.02f;furthest=Mathf.Max(furthest,puzzle.Root.InverseTransformPoint(ball.transform.position).z);}Require(furthest>-9&&furthest<0&&test.WorldPlay.Puzzle.solved==0,"Closed physical shutter let the ball through / rewarded");ball.ReturnHome();
   Dock();bool selected=false;for(int i=0;i<1200&&!puzzle.Open;i++){Tick(.05f);selected|=god.Owner==CreatureHybrid.ActionOwner.Curiosity&&mind.Current==CreatureCuriosity.Phase.PuzzleAssist;}Require(selected&&puzzle.Open&&puzzle.OnPad,"Creature did not choose/approach/hold pad: "+god.Explanation+" phase="+mind.Current+" distance="+Vector3.Distance(god.transform.position,puzzle.Pad.transform.position)/unit);Require(mind.Holding==null,"Puzzle seized the player key or ball");Require(!ball.Goals.Turns.Toggle(0)&&!ball.ReservePlay(people[0].GetComponent<VillagerExploration>()),"Another ball game stole the active puzzle");Require(puzzle.Cue==PuzzleCue.ReadyToRoll&&puzzle.LaunchVisible&&puzzle.ReadyChimes==1&&god.GetComponentInChildren<HumanoidHands>().indicating,"Open gate did not invite the player with a single sound/launch cue/gesture");readyCapture?.Invoke(ball);test.paused=true;var foot=god.transform.position;float cueClock=puzzle.CueClock;float lift=puzzle.Lift;Tick(1);Require(god.transform.position==foot&&puzzle.Lift==lift&&puzzle.CueClock==cueClock,"Paused puzzle moved");test.paused=false;
   // Exercise native ball pickup/drop while the creature continues holding the gate.
   Grab(ball.GetComponent<CarryItem>());Release(puzzle.LaunchPoint);Tick(.05f);Require(puzzle.Active&&puzzle.Open,"Ordinary ball placement canceled helper");// Carrying across is not a physical solution, including same-tick pickup/drop.
   Grab(ball.GetComponent<CarryItem>());ball.transform.position=puzzle.Root.TransformPoint(new Vector3(0,ball.Radius,6));Release(ball.transform.position);Tick(.05f);Require(test.WorldPlay.Puzzle.solved==0,"Carried ball solved the puzzle");
   // A tracking jump across the plane is also excluded.
   ball.PlaceOnGround(puzzle.LaunchPoint-Vector3.up*unit*ball.Radius);Tick(.02f);ball.Body.position=nav.ToNav(puzzle.Root.TransformPoint(new Vector3(0,ball.Radius,6)));Tick(.02f);Require(test.WorldPlay.Puzzle.solved==0,"Teleported ball solved the puzzle");
   Roll();for(int i=0;i<400&&test.WorldPlay.Puzzle.solved==0;i++)Tick(.02f);Tick(.02f);Require(test.WorldPlay.Puzzle.solved==1&&puzzle.Completed&&test.Hybrid.receipt.eligible&&test.Hybrid.receipt.target=="together-gate-pad"&&mind.Current==CreatureCuriosity.Phase.Rest,"Safe shared passage did not complete once: solved="+test.WorldPlay.Puzzle.solved+" phase="+mind.Current+" ball="+puzzle.Root.InverseTransformPoint(ball.transform.position));Require(!test.Hybrid.receipt.goal&&!test.Hybrid.receipt.fetched&&!test.Hybrid.receipt.spin,"Puzzle lesson conflated with a ball action");Require(puzzle.Cue==PuzzleCue.Solved&&!puzzle.LaunchVisible&&!god.GetComponentInChildren<HumanoidHands>().indicating,"Solved puzzle retained throw invitation or hand pose");capture?.Invoke(ball);Require(god.Feedback(true)&&!god.Feedback(true),"Puzzle teaching not once-only");for(int i=0;i<80;i++)ball.Advance(.05f,false);Require(test.WorldPlay.Puzzle.solved==1,"Stationary ball duplicated puzzle rewards");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Puzzle save invalid");
   Stage();Dock();for(int i=0;i<1200&&!puzzle.Open;i++)Tick(.05f);Require(puzzle.Open,"Second puzzle did not open");Grab(key);Tick(.05f);Require(!puzzle.Active&&!test.Hybrid.receipt.eligible&&test.WorldPlay.Puzzle.solved==1&&held[1]==key,"Key removal retained action/reward or stole key");Release(key.home);for(int i=0;i<30;i++)Tick(.05f);Require(puzzle.Lift==0&&puzzle.Cue==PuzzleCue.NeedsKey&&!puzzle.LaunchVisible,"Shutter/cues failed to reset after key removal");
   Stage();Dock();for(int i=0;i<1200&&!puzzle.Open;i++)Tick(.05f);Require(puzzle.Open,"Third puzzle did not open");god.Interrupt("QA interrupt");Require(!puzzle.Active&&!puzzle.LaunchVisible&&!test.Hybrid.receipt.eligible&&mind.Holding==null&&!god.GetComponentInChildren<HumanoidHands>().indicating,"Interruption retained puzzle, invitation, pose or lesson");Debug.Log("BWVR_PUZZLE_PLAY_PASS: closed-gate collisions, native key docking/ball drop, utility-selected navigation, pad hold/open, pause, safe physical passage, unique typed lesson/teaching/save, key removal and interruption cleanup");
  }finally{held[0]=held[1]=null;key.held=false;key.GetComponent<Collider>().enabled=true;god.Interrupt("Puzzle QA complete");field.SetValue(slice,original);god.NewSeason();ball.ResetWorld();foreach(var c in cooldowns)c.Key.cooldown=c.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);god.transform.SetPositionAndRotation(gp,gr);walker.ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.position=positions[i];people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
}
}
